                                + table + " WHERE " + ofSheet(table, "public"), sheetId);
                    }
                }
                if (snapshot == null && today != null && on.isBefore(today)) {
                    asOf.update("UPDATE asof.sheet SET archived = FALSE, last_settle_batch = 0 WHERE id = ?", sheetId);
                }
