import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';
import { useUser } from '../session/useSession';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** A holiday of the sheet: its date (yyyy-mm-dd). */
export type Holiday = { date: string };

/** The key every feature reads the sheet's holidays under. */
export const holidaysKey = (sheetId: string) => ['sheet', sheetId, 'holidays'] as const;

/** The sheet's holidays, by date. */
export function useHolidays(sheetId: string) {
  return useQuery({
    queryKey: holidaysKey(sheetId),
    queryFn: () => getJson<Holiday[]>(`/api/sheets/${encodeURIComponent(sheetId)}/holidays`),
  });
}

// The holiday list: a date entry adds a holiday; a date already on the list is refused. Every claim's due-by counts
// business days past the holidays on the sheet now, so a holiday added moves the due-bys (and the figures) it falls in.
function HolidaysPanel({ sheetId }: { sheetId: string; user: string }) {
  const holidays = useHolidays(sheetId);
  const [date, setDate] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: async (value: string) => {
      if (value.trim() === '') throw new Error('Enter a holiday date');
      if (!DATE.test(value.trim())) throw new Error('Enter a date as YYYY-MM-DD');
      // `by` is the signed-in user the change is recorded against.
      return postJson<Holiday>(`/api/sheets/${encodeURIComponent(sheetId)}/holidays`, { date: value.trim(), by: user ?? '' });
    },
    onSuccess: async () => {
      // The due-bys, and so the overdue figures and periods of the claims, follow the holidays: re-read the sheet.
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
      setDate('');
    },
  });

  const submit = useSubmitOnce(add);
  return (
    <section data-testid="holidays-panel">
      <h2>Holidays</h2>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submit(date);
        }}
      >
        <input
          type="date"
          data-testid="holiday-date"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="holiday-add" disabled={add.isPending}>
          Add holiday
        </button>
        {add.isError && (
          <span data-testid="holiday-error" role="alert">
            {' '}
            {add.error.message}
          </span>
        )}
      </form>
      <ul data-testid="holiday-list">
        {(holidays.data ?? []).map((h) => (
          <li key={h.date} data-testid={`holiday-row-${h.date}`}>
            {h.date}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 8, Component: HolidaysPanel });
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}

